    <script>
        // Slide navigation
        function scrollToSlide(slideNumber) {
            const slide = document.getElementById(`slide-${slideNumber}`);
            if (slide) {
                slide.scrollIntoView({ behavior: 'smooth' });
            }
        }

        // Update active dot on scroll
        const slides = document.querySelectorAll('.slide');
        const dots = document.querySelectorAll('.slide-nav-dot');

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const slideId = entry.target.id;
                    const slideNumber = parseInt(slideId.split('-')[1]);

                    dots.forEach((dot, index) => {
                        if (index === slideNumber - 1) {
                            dot.classList.add('active');
                        } else {
                            dot.classList.remove('active');
                        }
                    });
                }
            });
        }, {
            threshold: 0.5
        });

        slides.forEach(slide => {
            observer.observe(slide);
        });

        // Keyboard navigation
        document.addEventListener('keydown', (e) => {
            const currentSlide = Array.from(slides).findIndex(slide => {
                const rect = slide.getBoundingClientRect();
                return rect.top >= 0 && rect.top < window.innerHeight / 2;
            });

            if (e.key === 'ArrowDown' || e.key === 'PageDown' || e.key === ' ') {
                e.preventDefault();
                if (currentSlide < slides.length - 1) {
                    scrollToSlide(currentSlide + 2);
                }
            } else if (e.key === 'ArrowUp' || e.key === 'PageUp') {
                e.preventDefault();
                if (currentSlide > 0) {
                    scrollToSlide(currentSlide);
                }
            } else if (e.key === 'Home') {
                e.preventDefault();
                scrollToSlide(1);
            } else if (e.key === 'End') {
                e.preventDefault();
                scrollToSlide(slides.length);
            }
        });
    </script>

